"use strict";
const Lookbook = (()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keys=['brand','title','theme','facts','stage','email','url','dek','story','invitation'];
function valid(d){return d&&keys.every(k=>typeof d[k]==='string'&&d[k].length<=3000)&&Array.isArray(d.images)&&d.images.length<=10&&d.images.every(x=>x&&typeof x.id==='string'&&typeof x.caption==='string'&&x.caption.length<=250&&typeof x.selected==='boolean'&&/^data:image\/jpeg;base64,/.test(x.src)&&x.src.length<6000000);}
function copy(d){const title=d.title.trim()||'A study in personal expression',theme=d.theme.trim();return{dek:theme?`A collection shaped around ${theme.replace(/[.!?]+$/,'')}.`:'A closer look at form, feeling and the art of choosing.',story:`${title} begins with a point of view: jewelry as an expression of something personal.${theme?' Its starting point is '+theme.replace(/[.!?]+$/,'')+'.':''}\n\nThese images invite a slower look at the collection - its visual rhythm, its presence, and the details that draw you back.${d.facts?'\n\n'+d.facts:''}\n\nRather than asking for an immediate decision, this preview opens a conversation. Which image stays with you, and what would you like to explore further?`,invitation:'Tell us which image caught your eye. Include the page number and what you would like to know. This preview is an invitation to express interest, not an order confirmation.'};}
function destination(d){if(d.url){try{const u=new URL(d.url);if(u.protocol==='https:')return u.href;}catch{}}return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)?'mailto:'+d.email+'?subject='+encodeURIComponent('Interest in '+d.title):'';}
return{esc,valid,copy,destination,keys};})();
if(typeof module!=='undefined')module.exports=Lookbook;
if(typeof document!=='undefined'){
const {esc:e,keys}=Lookbook,$=s=>document.querySelector(s),form=$('#brief');let data=Object.fromEntries(keys.map(k=>[k,'']));data.stage='Concept preview';data.images=[];let db;
const status=t=>$('#status').textContent=t;
function read(){return {...data,...Object.fromEntries(new FormData(form)),images:data.images};}
function sync(){for(const k of keys)form.elements[k].value=data[k]||'';cards();preview();}
async function save(){data=read();if(!db)throw Error('Storage unavailable. Export an editable backup.');await new Promise((resolve,reject)=>{const tx=db.transaction('books','readwrite');tx.objectStore('books').put(data,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});status('Lookbook saved in this browser.');}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function cards(){$('#images').innerHTML=data.images.map((im,i)=>`<article class="image-card"><img src="${im.src}" alt="Selected editorial image ${i+1}"><label class="check"><input type="checkbox" data-select="${im.id}" ${im.selected?'checked':''}>Include in customer book</label><label>Caption / verified detail<input data-caption="${im.id}" value="${e(im.caption)}" maxlength="250"></label><div class="actions"><button type="button" data-move="${i}" data-dir="-1" ${i===0?'disabled':''}>Move up</button><button type="button" data-move="${i}" data-dir="1" ${i===data.images.length-1?'disabled':''}>Move down</button><button type="button" data-remove="${im.id}">Remove</button></div></article>`).join('');}
function preview(){const d=read(),ims=d.images.filter(x=>x.selected);if(!ims.length){$('#previewDeck').innerHTML='<div class="empty">Your magazine preview appears here after you add and select images.</div>';return;}const foot=(n)=>`<footer><span>${e(d.brand)} / ${e(d.stage)}</span><span>${n}</span></footer>`;$('#previewDeck').innerHTML=`<article class="sheet cover"><div class="kicker">${e(d.brand)} / COLLECTION PREVIEW</div><h2>${e(d.title||'Untitled collection')}</h2><p>${e(d.dek)}</p><img src="${ims[0].src}" alt="Cover selection">${foot('01')}</article><article class="sheet"><div class="kicker">THE STORY</div><h2>A closer look.</h2><p>${e(d.story).replace(/\n/g,'<br>')}</p>${foot('02')}</article>${ims.map((im,i)=>`<article class="sheet plate"><div class="kicker">PLATE ${String(i+1).padStart(2,'0')}</div><img src="${im.src}" alt="${e(im.caption||'Collection image')}"><p class="caption">${e(im.caption||'Collection study '+(i+1))}</p>${foot(String(i+3).padStart(2,'0'))}</article>`).join('')}<article class="sheet"><div class="kicker">THE CONVERSATION CONTINUES</div><h2>What caught<br>your eye?</h2><p>${e(d.invitation)}</p><p>${Lookbook.destination(d)?`<a href="${e(Lookbook.destination(d))}">Express your interest →</a>`:'Add an inquiry email or website.'}</p><p class="caption">${e(d.email)}<br>${e(d.stage)}. Specifications, availability and any pricing require confirmation.</p>${foot(String(ims.length+3).padStart(2,'0'))}</article>`;}
async function image(src){const im=new Image();im.src=src;await im.decode();if(!im.width||!im.height)throw Error('Image could not be read.');const scale=Math.min(1,2200/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(im,0,0,canvas.width,canvas.height);return {id:crypto.randomUUID(),src:canvas.toDataURL('image/jpeg',.88),caption:'',selected:true};}
$('#upload').onchange=async ev=>{try{data=read();for(const f of ev.target.files){if(data.images.length>=10)throw Error('Maximum ten images.');if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>12000000)throw Error('Use JPG/PNG/WebP files up to 12 MB.');const src=await new Promise((r,j)=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(f);});data.images.push(await image(src));}cards();preview();await save();}catch(err){cards();preview();status(err.message);}finally{ev.target.value='';}};
$('#images').oninput=ev=>{const x=data.images.find(x=>x.id===ev.target.dataset.caption);if(x)x.caption=ev.target.value;};$('#images').onchange=ev=>{const x=data.images.find(x=>x.id===ev.target.dataset.select);if(x)x.selected=ev.target.checked;preview();};$('#images').onclick=ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.remove)data.images=data.images.filter(x=>x.id!==b.dataset.remove);if(b.dataset.move!==undefined){const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);if(j>=0&&j<data.images.length)[data.images[i],data.images[j]]=[data.images[j],data.images[i]];}cards();preview();};
$('#write').onclick=()=>{const d=read();if((d.story||d.dek)&&!confirm('Replace the current story and opening line with new starter copy?'))return;Object.assign(data,d,Lookbook.copy(d));sync();status('Editable starter story created from your brief. Review it against the images and confirmed facts.');};
form.onsubmit=ev=>{ev.preventDefault();save().catch(err=>status(err.message));};$('#preview').onclick=preview;
$('#backup').onclick=()=>download('editorial-lookbook.json',new Blob([JSON.stringify(read())],{type:'application/json'}));
$('#restore').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>60000000)throw Error('Backup exceeds 60 MB.');const d=JSON.parse(await f.text());if(!Lookbook.valid(d))throw Error('Invalid lookbook backup.');if(!confirm('Replace this lookbook? Export your current book first if needed.'))return;data=d;sync();await save();}catch(err){status(err.message);}finally{ev.target.value='';}};
$('#prompt').onclick=()=>{const d=read();download('editorial-story-prompt.txt',new Blob(['Write refined customer-facing jewelry editorial copy from this brief. Return a short opening line, a 150-word story, image captions for manual review and an inquiry invitation. Do not invent materials, provenance, availability, testimonials or craftsmanship. Do not claim to see images unless they are attached. Use original fashion-editorial language, not a magazine trademark or an implied endorsement.\n'+JSON.stringify({...d,images:d.images.map((x,i)=>({page:i+3,caption:x.caption}))},null,2)],{type:'text/plain'}));};
$('#import').onclick=async()=>{try{data=read();const work=await new Promise((resolve,reject)=>{const r=indexedDB.open('jewelry-workbench',1);r.onupgradeneeded=()=>{r.transaction.abort();reject(Error('No Workbench data yet. Upload images above.'));};r.onerror=()=>reject(Error('No saved Workbench available.'));r.onsuccess=()=>resolve(r.result);});let stored;try{stored=await new Promise((r,j)=>{const q=work.transaction('workspace').objectStore('workspace').get('current');q.onsuccess=()=>r(q.result);q.onerror=j;});}finally{work.close();}const found=new Set();function walk(v){if(typeof v==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(v))found.add(v);else if(v&&typeof v==='object')Object.values(v).forEach(walk);}walk(stored);let count=0;for(const src of found){if(data.images.length>=10)break;const im=await image(src);if(!data.images.some(x=>x.src===im.src)){im.selected=false;data.images.push(im);count++;}}cards();preview();status(`${count} images found. Select only approved customer-facing visuals; check captions and order.`);}catch(err){status(err.message);}};
$('#pdf').onclick=async()=>{const b=$('#pdf');try{const d=read(),ims=d.images.filter(x=>x.selected);if(!d.brand.trim()||!d.title.trim()||!d.story.trim())throw Error('Add brand, collection title and story.');if(!ims.length)throw Error('Select at least one image.');if(!Lookbook.destination(d))throw Error('Add a valid inquiry email or https website.');if(!$('#approved').checked)throw Error('Complete the review checkbox before exporting.');b.disabled=true;status('Composing your editorial PDF…');const {jsPDF}=window.jspdf,pdf=new jsPDF({unit:'mm',format:'a4',compress:true});pdf.setProperties({title:d.title+' - '+d.brand,author:d.brand,subject:'Customer interest collection preview'});let page=0;
function base(dark=false){page++;pdf.setFillColor(dark?'#171713':'#f3efe7');pdf.rect(0,0,210,297,'F');pdf.setTextColor(dark?'#f3efe7':'#171713');pdf.setFont('helvetica','normal');pdf.setFontSize(8);pdf.text(d.brand.toUpperCase().slice(0,70),18,18);pdf.setDrawColor('#aa9772');pdf.line(18,275,192,275);pdf.setFontSize(7);pdf.text(d.stage+' / '+String(page).padStart(2,'0'),18,282);}
function lines(t,x,y,w,size,font='times',limit=100){pdf.setFont(font,'normal');pdf.setFontSize(size);const arr=pdf.splitTextToSize(t,w);if(arr.length>limit)throw Error('Copy is too long for the designed page. Shorten the story or caption.');pdf.text(arr,x,y,{lineHeightFactor:1.35});return y+arr.length*size*.3528*1.35;}
async function photo(im,x,y,w,h){const decoded=new Image();decoded.src=im.src;await decoded.decode();const scale=Math.min(w/decoded.width,h/decoded.height),iw=decoded.width*scale,ih=decoded.height*scale;pdf.addImage(im.src,'JPEG',x+(w-iw)/2,y+(h-ih)/2,iw,ih,undefined,'FAST');}
base(true);lines(d.title,18,42,174,37,'times',3);lines(d.dek,18,91,170,13,'times',3);await photo(ims[0],18,119,174,142);pdf.addPage();base();lines('The story',18,48,174,36);lines(d.story,18,73,166,14,'times',27);
for(let i=0;i<ims.length;i++){pdf.addPage();base();pdf.setFontSize(8);pdf.text('PLATE '+String(i+1).padStart(2,'0'),18,32);await photo(ims[i],18,40,174,198);lines(ims[i].caption||'Collection study '+(i+1),18,250,174,10,'helvetica',4);}
pdf.addPage();base();lines('What caught your eye?',18,58,165,36,'times',3);lines(d.invitation,18,110,165,15,'times',8);pdf.setFillColor('#171713');pdf.rect(18,181,125,14,'F');pdf.setTextColor('#f3efe7');pdf.setFont('helvetica','normal');pdf.setFontSize(10);pdf.text('EXPRESS YOUR INTEREST',23,190);pdf.link(18,181,125,14,{url:Lookbook.destination(d)});pdf.setTextColor('#171713');lines(d.email||d.url,18,210,170,10,'helvetica',3);lines(d.stage+'. Specifications, availability and any pricing require confirmation.',18,238,170,9,'helvetica',4);pdf.save((d.title.replace(/[^a-z0-9]+/gi,'-')||'collection')+'-editorial.pdf');await save();status('PDF downloaded and lookbook saved. Review the file before sending to customers.');}catch(err){status(err.message);}finally{b.disabled=false;}};
(async()=>{try{db=await new Promise((r,j)=>{const q=indexedDB.open('jewelry-editorial-lookbook',1);q.onupgradeneeded=()=>q.result.createObjectStore('books');q.onsuccess=()=>r(q.result);q.onerror=j;});const stored=await new Promise((r,j)=>{const q=db.transaction('books').objectStore('books').get('current');q.onsuccess=()=>r(q.result);q.onerror=j;});if(stored){if(!Lookbook.valid(stored))throw Error('Saved lookbook is invalid. Restore a backup.');data=stored;}sync();status('Ready. Images and copy stay on this browser.');}catch(err){status(err.message);}})();
}
